//! 🧪️ The actual decoder returns only replies deposited by its original construction producer.
use semio_framework_value_native_decoding::*;
 use semio_framework_value_control_contract::{OriginalConstructionAuthority,OriginalConstructionRecipient,OriginalConstructionGrant,OriginalConstructionGrantComplete,OriginalConstructionAccept,OriginalConstructionAcceptComplete};
 struct Source{binding:std::sync::Arc<u8>,grant_interrupt:bool,receipt_interrupt:bool}
 impl OriginalConstructionRecipient for Source{
  type Context<'turn,'source>=&'turn u8 where 'source:'turn;
  fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity>where 'source:'turn{None}
  fn validate_context<'turn,'source>(&self,context:&&'turn u8)->Result<(),ValueError> where 'source:'turn{if std::ptr::eq(self.binding.as_ref(),*context){Ok(())}else{Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original construction context changed"))}}
  fn grant<'a,'turn,'source>(&mut self,_:&mut &'turn u8,quote:OriginalConstructionGrant<'a>)->OriginalConstructionGrantComplete<'a> where 'source:'turn{let d=quote.demand();let done=quote.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}));if self.grant_interrupt{self.grant_interrupt=false;panic!("grant reply recorded")}done}
  fn accept<'a,'turn,'source>(&mut self,_:&mut &'turn u8,receipt:OriginalConstructionAccept<'a>)->OriginalConstructionAcceptComplete<'a> where 'source:'turn{assert_eq!(receipt.actual(),Some(0));let done=receipt.complete(Err(ValueError::literal(ValueRefusalKind::Canceled,"original decoder receipt refusal")));if self.receipt_interrupt{self.receipt_interrupt=false;panic!("receipt reply recorded")}done}
  fn submitted<'turn,'source>(&self,_:&&'turn u8)->RetainedCloneProgress where 'source:'turn{Default::default()}
 }
 struct Work;impl OriginalWorkRecipient for Work{
 type Context<'turn,'source>=() where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn admits<'a,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,quote:OriginalWorkQuote<'a>,_:u64,_:u64)->OriginalWorkQuoteComplete<'a>where 'source:'turn{quote.complete(Ok(true))}
 }
 fn work_turn<T>(work:&mut OriginalWorkAuthority<Work>,native:&mut NativeDecodeControl<'_>,operation:impl FnOnce(&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<T,ValueError>{work.with_loan(&mut (),|loan|native.with_work_recipient(loan,operation))?}
 #[test]
 fn decoder_recovers_only_producer_recorded_replies_through_the_original_authority(){
  let binding=std::sync::Arc::new(1);let foreign_binding=std::sync::Arc::new(2);
  let mut authority=OriginalConstructionAuthority::new(Source{binding:binding.clone(),grant_interrupt:true,receipt_interrupt:true});
  let mut foreign=OriginalConstructionAuthority::new(Source{binding:foreign_binding.clone(),grant_interrupt:false,receipt_interrupt:false});
  let mut context=binding.as_ref();let mut foreign_context=foreign_binding.as_ref();let mut observer=|_|true;let mut native=NativeDecodeControl::new(0,&mut observer);let mut frame=NativeReceivingEffect::<ValueError>::default();let mut work=OriginalWorkAuthority::new(Work);work_turn(&mut work,&mut native,|native|{
  let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||authority.with_loan(&mut context,|loan|native.with_construction_recipient(loan,|control|frame.quote(control,RetirementDemand{depth:1,..Default::default()})))));
  assert!(interrupted.is_err());assert_eq!(frame.phase(),NativeReceivingEffectPhase::GrantStarted);
  foreign.with_loan(&mut foreign_context,|loan|native.with_construction_recipient(loan,|control|{assert!(frame.recover_grant(control).is_err());Ok::<_,ValueError>(())})).unwrap().unwrap();
  authority.with_loan(&mut context,|loan|native.with_construction_recipient(loan,|control|{assert!(frame.recover_grant(control)?);assert_eq!(frame.prepare_work(control,0)?,Some(true));frame.effect_unallocated(control,|marker,_|{*marker=Some(0);RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}})?;frame.settle_original_work(control,0)})).unwrap().unwrap();
  let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||authority.with_loan(&mut context,|loan|native.with_construction_recipient(loan,|control|frame.receipt(control)))));
  assert!(interrupted.is_err());assert_eq!(frame.phase(),NativeReceivingEffectPhase::ReceiptStarted);
  let turn=authority.with_loan(&mut context,|loan|native.with_construction_recipient(loan,|control|{assert!(frame.recover_receipt(control)?);frame.take(control)})).unwrap().unwrap();
  assert_eq!(turn.result.unwrap_err().receiving.receipt_refusal.unwrap().message.as_ref(),"original decoder receipt refusal");
  assert!(authority.into_recipient().is_ok());assert!(foreign.into_recipient().is_ok());Ok::<_,ValueError>(())}).unwrap();
 }

type Events=std::sync::Arc<std::sync::Mutex<Vec<&'static str>>>;
struct Allocation{binding:std::sync::Arc<u8>,budget:NativeAllocationBudget,events:Events}
impl NativeAllocationAuthorityPort for Allocation{
 type Context<'turn,'source>=(&'turn u8,RetainedCloneGrant) where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,context:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{if std::ptr::eq(self.binding.as_ref(),context.0){Ok(())}else{Err(ValueError::invariant("original allocation context changed"))}}
 fn receive<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,event:NativeAllocationEvent,reply:NativeAllocationReply<'reply>)->Result<NativeAllocationReplyComplete<'reply>,ValueError>where 'source:'turn{if matches!(event,NativeAllocationEvent::Quote(_)){self.budget.begin_hop()}let result=self.budget.receive(event,context.1,true).map_err(Into::into);let completed=reply.complete(result);if matches!(event,NativeAllocationEvent::Post{..}){self.events.lock().unwrap().push("post");panic!("actual allocation Post reply recorded")}Ok(completed)}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,_:NativeAllocationEvent,reply:NativeAllocationReply<'reply>)->Result<NativeAllocationReplyComplete<'reply>,ValueError>where 'source:'turn{Ok(reply.pending())}
}
struct ConstructionPost{binding:std::sync::Arc<u8>,events:Events}
impl OriginalConstructionRecipient for ConstructionPost{
 type Context<'turn,'source>=&'turn u8 where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,context:&&'turn u8)->Result<(),ValueError>where 'source:'turn{if std::ptr::eq(self.binding.as_ref(),*context){Ok(())}else{Err(ValueError::invariant("original physical context changed"))}}
 fn grant<'a,'turn,'source>(&mut self,_:&mut &'turn u8,quote:OriginalConstructionGrant<'a>)->OriginalConstructionGrantComplete<'a>where 'source:'turn{let d=quote.demand();quote.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}))}
 fn accept<'a,'turn,'source>(&mut self,_:&mut &'turn u8,receipt:OriginalConstructionAccept<'a>)->OriginalConstructionAcceptComplete<'a>where 'source:'turn{assert_eq!(receipt.actual(),Some(receipt.progress().retained_capacity_bytes));self.events.lock().unwrap().push("receipt");receipt.complete(Ok(()))}
 fn submitted<'turn,'source>(&self,_:&&'turn u8)->RetainedCloneProgress where 'source:'turn{Default::default()}
}
#[test]
fn physical_post_unwind_keeps_original_cpu_proof_and_real_allocation(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("cpu-post.json")).unwrap();let bytes=fixture["bytes"].as_u64().unwrap()as usize;let units=fixture["work"].as_u64().unwrap();
 let binding=std::sync::Arc::new(3);let events=std::sync::Arc::new(std::sync::Mutex::new(Vec::with_capacity(8)));
 let mut allocation=NativeAllocationAuthority::new(Allocation{binding:binding.clone(),budget:Default::default(),events:events.clone()});let mut physical=OriginalConstructionAuthority::new(ConstructionPost{binding:binding.clone(),events:events.clone()});
 let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:bytes,maximum_release_bytes:bytes,maximum_depth:8};let mut allocation_context=(binding.as_ref(),grant);let mut physical_context=binding.as_ref();
 let mut work=OriginalWorkAuthority::new(Work);let mut output=None;let mut frame=NativeReceivingEffect::<ValueError>::default();
 allocation.with_send_loan(&mut allocation_context,|allocation|{
  let mut observer=|_|true;let mut native=NativeDecodeControl::new_forwarded(bytes,&mut observer,allocation);
  let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||work_turn(&mut work,&mut native,|native|physical.with_loan(&mut physical_context,|physical|native.with_construction_recipient(physical,|control|{
   frame.quote(control,RetirementDemand{capacity_bytes:bytes,depth:1,..Default::default()})?;assert_eq!(frame.prepare_work(control,units)?,Some(true));
   frame.effect(control,|actual,_|{let (owner,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||{*actual=Some(0);let layout=std::alloc::Layout::array::<u8>(bytes).unwrap();let pointer=unsafe{std::alloc::alloc(layout)};assert!(!pointer.is_null());*actual=Some(bytes);unsafe{Vec::from_raw_parts(pointer,0,bytes)}});assert_eq!(heap,(bytes,0));output=Some(owner);events.lock().unwrap().push("child");RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{retained_capacity_bytes:bytes,..Default::default()})),work:units}})?;
   assert_eq!(frame.phase(),NativeReceivingEffectPhase::EffectStarted);frame.settle_original_work(control,units)?;assert_eq!(control.actual_work(),units);events.lock().unwrap().push("commit");frame.finish_allocation(control)
  })).map_err(|error|error)?)));
  assert!(interrupted.is_err());assert_eq!(native.actual_work(),fixture["expected"]["committedAtPost"].as_u64().unwrap());assert_eq!(output.as_ref().unwrap().capacity(),fixture["expected"]["capacityAtPost"].as_u64().unwrap()as usize);assert_eq!(native.has_pending_work(),fixture["expected"]["proofLiveAfterInterruption"].as_bool().unwrap());
  let pointer=output.as_ref().unwrap().as_ptr();let turn=work_turn(&mut work,&mut native,|native|physical.with_loan(&mut physical_context,|physical|native.with_construction_recipient(physical,|control|{assert!(frame.recover_allocation_callback(control).expect("recover original Post reply"));events.lock().unwrap().push("recover");frame.finish_allocation(control).expect("finish original allocation");frame.receipt(control).expect("submit original construction receipt");let turn=frame.take(control).expect("return original receipt and CPU proof");events.lock().unwrap().push("finish");Ok::<_,ValueError>(turn)})).map_err(|error|error)?).unwrap();
  assert!(turn.result.is_ok());assert_eq!(turn.work,units);assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(!native.has_pending_work(),fixture["expected"]["proofReturnedAfterReceipt"].as_bool().unwrap());
 }).unwrap();
 assert_eq!(serde_json::to_value(&*events.lock().unwrap()).unwrap(),fixture["events"]);
 assert!(allocation.into_port().is_ok());assert!(physical.into_recipient().is_ok());drop(output.take());
}

struct Cleanup{binding:std::sync::Arc<u8>,receipts:std::sync::Arc<std::sync::atomic::AtomicUsize>}
impl OriginalConstructionRecipient for Cleanup{
 type Context<'turn,'source>=&'turn u8 where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,context:&&'turn u8)->Result<(),ValueError>where 'source:'turn{if std::ptr::eq(self.binding.as_ref(),*context){Ok(())}else{Err(ValueError::invariant("original cleanup source changed"))}}
 fn grant<'a,'turn,'source>(&mut self,_:&mut &'turn u8,quote:OriginalConstructionGrant<'a>)->OriginalConstructionGrantComplete<'a>where 'source:'turn{let d=quote.demand();quote.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}))}
 fn accept<'a,'turn,'source>(&mut self,_:&mut &'turn u8,receipt:OriginalConstructionAccept<'a>)->OriginalConstructionAcceptComplete<'a>where 'source:'turn{assert_eq!(receipt.actual(),None);assert_eq!(receipt.progress().retained_capacity_bytes,0);self.receipts.fetch_add(1,std::sync::atomic::Ordering::Relaxed);receipt.complete(Ok(()))}
 fn submitted<'turn,'source>(&self,_:&&'turn u8)->RetainedCloneProgress where 'source:'turn{Default::default()}
}
#[test]
fn canceled_semantic_observer_still_lends_the_real_cleanup_effect(){
 use semio_framework_value_retirement::retirement::{RetireOwned,RetirementCursor,RetirementStep};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("cpu-post.json")).unwrap();let law=&fixture["cleanup"];let payload=law["text"].as_str().unwrap().to_owned();let bytes=payload.capacity();let(mut cursor,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||payload.retirement_seed());assert_eq!(heap,(0,0));
 let binding=std::sync::Arc::new(4);let receipts=std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));let mut physical=OriginalConstructionAuthority::new(Cleanup{binding:binding.clone(),receipts:receipts.clone()});let mut context=binding.as_ref();let mut work=OriginalWorkAuthority::new(Work);let mut observer=|_|false;let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(0,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let ledger=native.ledger_identity();let mut frame=NativeReceivingEffect::<semio_framework_value_retirement::OriginalRetirementFailure>::default();let mut released=0;let mut consumed=0;
 for _ in 0..16{if cursor.terminal_is_empty(){break}let demand=cursor.next_demand(4096).unwrap();let units=cursor.next_computational_work(4096).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};
  let poll=work_turn(&mut work,&mut native,|native|physical.with_loan(&mut context,|physical|native.with_construction_recipient(physical,|control|control.with_retirement(grant,|funding|funding.receive_effect(demand,units,&mut frame,|funding,effect|{assert_eq!(funding.ledger_identity(),ledger);let (step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||cursor.close_step(effect));match step{RetirementStep::Progress(progress,work)=>{assert_eq!(heap,(0,progress.released_bytes));RetainedWorkOutcome{result:Ok(if cursor.terminal_is_empty(){RetainedCloneStep::Complete(progress)}else{RetainedCloneStep::Progress(progress)}),work}},RetirementStep::Complete(work)=>{assert_eq!(heap,(0,0));RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work}},RetirementStep::Failure(error,work)=>RetainedWorkOutcome{result:Err(error),work},_=>panic!("String cleanup must retain its own concrete seed")}})))).map_err(|error|error)?).unwrap();
  let NativeReceivingEffectPoll::Complete(turn)=poll else{panic!("admitted original cleanup remained pending")};consumed+=turn.work;released+=turn.result.unwrap().progress().released_bytes;assert!(!native.has_pending_work());
 }
 assert_eq!(consumed,law["work"].as_u64().unwrap());assert_eq!(released,law["expectedRelease"].as_u64().unwrap()as usize);assert_eq!(released,bytes);assert!(cursor.terminal_is_empty());assert_eq!(receipts.load(std::sync::atomic::Ordering::Relaxed),law["posts"].as_u64().unwrap()as usize);assert!(physical.into_recipient().is_ok());assert!(work.into_recipient().is_ok());
}

struct RefusingWork{reject:std::sync::Arc<std::sync::atomic::AtomicBool>,refusal:std::sync::Mutex<Option<ValueError>>}
impl OriginalWorkRecipient for RefusingWork{
 type Context<'turn,'source>=() where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{if self.reject.load(std::sync::atomic::Ordering::Relaxed){Err(self.refusal.lock().unwrap().take().expect("actual original work refusal retained until validation"))}else{Ok(())}}
 fn admits<'a,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,quote:OriginalWorkQuote<'a>,_:u64,_:u64)->OriginalWorkQuoteComplete<'a>where 'source:'turn{quote.complete(Ok(true))}
}
#[test]
fn actual_overrun_keeps_the_original_child_and_prior_work_refusal(){
 let all:serde_json::Value=serde_json::from_str(include_str!("cpu-post.json")).unwrap();let law=&all["workOverrun"];let child=ValueError::new(ValueRefusalKind::InvalidValue,law["childError"].as_str().unwrap());let child_pointer=child.message.as_ptr();let work_error=ValueError::new(ValueRefusalKind::Canceled,law["workError"].as_str().unwrap());let work_pointer=work_error.message.as_ptr();let mut child=Some(child);
 let reject=std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));let mut work=OriginalWorkAuthority::new(RefusingWork{reject:reject.clone(),refusal:std::sync::Mutex::new(Some(work_error))});let binding=std::sync::Arc::new(5);let receipts=std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));let mut physical=OriginalConstructionAuthority::new(Cleanup{binding:binding.clone(),receipts});let mut context=binding.as_ref();let mut observer=|_|true;let mut native=NativeDecodeControl::new(0,&mut observer);let mut frame=NativeReceivingEffect::<ValueError>::default();let mut calls=0;
 let turn=work.with_loan(&mut (),|loan|native.with_work_recipient(loan,|native|physical.with_loan(&mut context,|physical|native.with_construction_recipient(physical,|control|{frame.quote(control,RetirementDemand{depth:1,..Default::default()})?;assert_eq!(frame.prepare_work(control,law["quoted"].as_u64().unwrap())?,Some(true));frame.effect_unallocated(control,|_,_|{calls+=1;RetainedWorkOutcome{result:Err(child.take().unwrap()),work:law["performed"].as_u64().unwrap()}})?;reject.store(true,std::sync::atomic::Ordering::Relaxed);assert!(frame.settle_original_work(control,law["performed"].as_u64().unwrap()).is_err());reject.store(false,std::sync::atomic::Ordering::Relaxed);frame.retry_original_work(control)?;assert_eq!(control.actual_work(),law["performed"].as_u64().unwrap());frame.receipt(control)?;frame.take(control)})).map_err(|error|error)?)).unwrap().unwrap();
 let failure=turn.result.unwrap_err();assert_eq!(failure.child.as_ref().unwrap().message.as_ptr(),child_pointer);assert_eq!(failure.work_refusal.as_ref().unwrap().message.as_ptr(),work_pointer);assert_eq!(failure.receiving.work_overrun.as_ref().unwrap().kind,ValueRefusalKind::WorkLimit);assert_eq!(calls,law["effectCalls"].as_u64().unwrap());assert_eq!(usize::from(failure.child.is_some())+usize::from(failure.work_refusal.is_some())+usize::from(failure.receiving.work_overrun.is_some()),law["retainedCauses"].as_u64().unwrap()as usize);assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());
}

struct AllocationSource{budget:NativeAllocationBudget,pending:Option<Result<(),NativeAllocationRefusal>>,quotes:usize,defer_quote:bool,posts:usize,cancels:usize}
impl NativeAllocationAuthorityPort for AllocationSource{
 type Context<'turn,'source>=RetainedCloneGrant where 'source:'turn;
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn validate_context<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn receive<'reply,'turn,'source>(&mut self,grant:&mut Self::Context<'turn,'source>,event:NativeAllocationEvent,reply:NativeAllocationReply<'reply>)->Result<NativeAllocationReplyComplete<'reply>,ValueError>where 'source:'turn{if matches!(event,NativeAllocationEvent::Quote(_)){self.budget.begin_hop();self.quotes+=1;assert!(self.pending.is_none());let verdict=self.budget.receive(event,*grant,true).map_err(Into::into);if self.defer_quote{self.pending=Some(verdict);Ok(reply.pending())}else{Ok(reply.complete(verdict))}}else{if matches!(event,NativeAllocationEvent::Post{..}){self.posts+=1}if matches!(event,NativeAllocationEvent::Cancel(_)){self.cancels+=1}Ok(reply.complete(self.budget.receive(event,*grant,true).map_err(Into::into)))}}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,event:NativeAllocationEvent,reply:NativeAllocationReply<'reply>)->Result<NativeAllocationReplyComplete<'reply>,ValueError>where 'source:'turn{assert!(matches!(event,NativeAllocationEvent::Quote(_)));Ok(reply.complete(self.pending.take().expect("original producer owns the pending quote verdict")))}
}
#[test]
fn pending_original_quote_runs_no_child_until_its_actual_source_recovers(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("cpu-post.json")).unwrap();let law=&fixture["pendingQuote"];let bytes=law["bytes"].as_u64().unwrap()as usize;let units=law["work"].as_u64().unwrap();let binding=std::sync::Arc::new(6);let events=std::sync::Arc::new(std::sync::Mutex::new(Vec::with_capacity(4)));let mut physical=OriginalConstructionAuthority::new(ConstructionPost{binding:binding.clone(),events});let mut context=binding.as_ref();let mut work=OriginalWorkAuthority::new(Work);let mut allocation=NativeAllocationAuthority::new(AllocationSource{budget:Default::default(),pending:None,quotes:0,defer_quote:true,posts:0,cancels:0});let mut grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:bytes,maximum_release_bytes:bytes,maximum_depth:8};let mut output=None;let mut calls=0;let mut frame=NativeReceivingEffect::<ValueError>::default();
 allocation.with_send_loan(&mut grant,|allocation|{let mut observer=|_|true;let mut native=NativeDecodeControl::new_forwarded(bytes,&mut observer,allocation);work_turn(&mut work,&mut native,|native|physical.with_loan(&mut context,|physical|native.with_construction_recipient(physical,|control|{
 frame.quote(control,RetirementDemand{capacity_bytes:bytes,depth:1,..Default::default()})?;assert_eq!(frame.prepare_work(control,units)?,Some(true));frame.effect(control,|_,_|{calls+=1;panic!("pending original quote must not invoke the actual child")})?;assert_eq!(calls,law["effectCallsBeforeRecovery"].as_u64().unwrap());assert_eq!(frame.phase(),NativeReceivingEffectPhase::EffectStarted);assert!(frame.recover_allocation_callback(control)?);
 frame.resume_effect(control,|actual,_|{calls+=1;let(owner,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||{*actual=Some(0);let pointer=unsafe{std::alloc::alloc(std::alloc::Layout::array::<u8>(bytes).unwrap())};assert!(!pointer.is_null());*actual=Some(bytes);unsafe{Vec::from_raw_parts(pointer,0,bytes)}});assert_eq!(heap,(bytes,0));output=Some(owner);RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{retained_capacity_bytes:bytes,..Default::default()})),work:units}})?;let pointer=output.as_ref().unwrap().as_ptr();frame.settle_original_work(control,units)?;frame.finish_allocation(control)?;frame.receipt(control)?;let turn=frame.take(control)?;assert!(turn.result.is_ok());assert_eq!(turn.work,units);assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(calls,law["effectCallsAfterRecovery"].as_u64().unwrap());assert!(!control.has_pending_work());Ok::<_,ValueError>(())
 })).map_err(|error|error)?).unwrap()}).unwrap();let port=allocation.into_port().ok().unwrap();assert_eq!(port.quotes,law["quoteCalls"].as_u64().unwrap()as usize);assert!(port.pending.is_none());assert!(physical.into_recipient().is_ok());assert!(work.into_recipient().is_ok());drop(output.take());
}

#[test]
fn interrupted_work_is_transferred_once(){
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🔨️modules/🌱️value/🛬️decode/🏭️construction/🧪️tests/🧫️fixtures/effect-frame.json")).unwrap();let law=&fixture["workRecovery"];let binding=std::sync::Arc::new(7);let events=std::sync::Arc::new(std::sync::Mutex::new(Vec::with_capacity(2)));let mut physical=OriginalConstructionAuthority::new(ConstructionPost{binding:binding.clone(),events});let mut context=binding.as_ref();let mut work=OriginalWorkAuthority::new(Work);let mut observer=|_|true;let mut native=NativeDecodeControl::new(0,&mut observer);let mut frame=NativeReceivingEffect::<ValueError>::default();
 let turn=work_turn(&mut work,&mut native,|native|physical.with_loan(&mut context,|loan|native.with_construction_recipient(loan,|control|{frame.quote(control,RetirementDemand{depth:1,..Default::default()})?;assert!(!semio_framework_value_retirement::retirement::RetireOwned::retirement_ready(&frame));assert!(semio_framework_value_retirement::retirement::RetireOwned::retirement_birth_bytes(&frame).is_none());assert_eq!(frame.prepare_work(control,law["child"].as_u64().unwrap())?,Some(true));frame.effect(control,|actual,_|{*actual=Some(0);RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:law["child"].as_u64().unwrap()}})?;assert_eq!(frame.claim_child_work(),law["interrupted"].as_u64().unwrap());assert_eq!(frame.claim_child_work(),0);frame.settle_original_work(control,law["child"].as_u64().unwrap())?;frame.finish_allocation(control)?;frame.receipt(control)?;frame.take(control)})).map_err(|error|error)?).unwrap();
 assert_eq!(turn.work,law["settled"].as_u64().unwrap());assert!(turn.result.is_ok());assert!(physical.into_recipient().is_ok());assert!(work.into_recipient().is_ok());
}
#[test]
fn missing_marker_keeps_real_owner_and_quote_pending_until_resolution(){
 let bytes=5;let binding=std::sync::Arc::new(8);let events=std::sync::Arc::new(std::sync::Mutex::new(Vec::with_capacity(2)));let mut physical=OriginalConstructionAuthority::new(ConstructionPost{binding:binding.clone(),events});let mut context=binding.as_ref();let mut work=OriginalWorkAuthority::new(Work);let mut allocation=NativeAllocationAuthority::new(AllocationSource{budget:Default::default(),pending:None,quotes:0,defer_quote:false,posts:0,cancels:0});let mut grant=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:bytes,maximum_depth:1,..Default::default()};let mut owner=Vec::<u8>::new();let mut frame=NativeReceivingEffect::<ValueError>::default();
 allocation.with_send_loan(&mut grant,|allocation|{let mut observer=|_|true;let mut native=NativeDecodeControl::new_forwarded(bytes,&mut observer,allocation);let turn=work_turn(&mut work,&mut native,|native|physical.with_loan(&mut context,|loan|native.with_construction_recipient(loan,|control|{
 frame.quote(control,RetirementDemand{capacity_bytes:bytes,depth:1,..Default::default()})?;assert_eq!(frame.prepare_work(control,1)?,Some(true));frame.effect(control,|_,_|{let pointer=unsafe{std::alloc::alloc(std::alloc::Layout::array::<u8>(bytes).unwrap())};assert!(!pointer.is_null());owner=unsafe{Vec::from_raw_parts(pointer,0,bytes)};RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{retained_capacity_bytes:bytes,..Default::default()})),work:1}})?;frame.settle_original_work(control,1)?;assert_eq!(frame.phase(),NativeReceivingEffectPhase::EffectStarted);assert!(frame.finish_allocation(control).is_err());assert_eq!(owner.capacity(),bytes);frame.resolve_effect_marker(control,Some(owner.capacity()))?;frame.finish_allocation(control)?;frame.receipt(control)?;frame.take(control)
 })).map_err(|error|error)?).unwrap();assert_eq!(turn.work,1);let failure=turn.result.unwrap_err();assert_eq!(failure.receiving.primary.as_ref().unwrap().kind,ValueRefusalKind::InvariantViolated);assert_eq!(failure.receiving.progress.retained_capacity_bytes,bytes);assert_eq!(owner.capacity(),bytes);}).unwrap();let source=allocation.into_port().ok().unwrap();assert_eq!(source.quotes,1);assert_eq!(source.posts,1);assert_eq!(source.cancels,0);assert!(physical.into_recipient().is_ok());assert!(work.into_recipient().is_ok());drop(owner);
}

#[test]
fn normal_receiving_poll_preserves_pending_and_returns_the_actual_effect(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("cpu-post.json")).unwrap();let law=&fixture["pendingQuote"];let bytes=law["bytes"].as_u64().unwrap()as usize;let units=law["work"].as_u64().unwrap();let binding=std::sync::Arc::new(9);let events=std::sync::Arc::new(std::sync::Mutex::new(Vec::with_capacity(2)));let mut physical=OriginalConstructionAuthority::new(ConstructionPost{binding:binding.clone(),events});let mut context=binding.as_ref();let mut work=OriginalWorkAuthority::new(Work);let mut allocation=NativeAllocationAuthority::new(AllocationSource{budget:Default::default(),pending:None,quotes:0,defer_quote:true,posts:0,cancels:0});let mut grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:bytes,maximum_release_bytes:bytes,maximum_depth:8};let mut output=None;let mut calls=0;let mut frame=NativeReceivingEffect::<ValueError>::default();
 allocation.with_send_loan(&mut grant,|allocation|{let mut observer=|_|true;let mut native=NativeDecodeControl::new_forwarded(bytes,&mut observer,allocation);work_turn(&mut work,&mut native,|native|physical.with_loan(&mut context,|physical|native.with_construction_recipient(physical,|control|{
 let demand=RetirementDemand{capacity_bytes:bytes,depth:1,..Default::default()};let poll=control.receive_effect(demand,units,&mut frame,|_,_|panic!("pending quote invoked a child"));assert!(matches!(poll?,NativeReceivingEffectPoll::Pending{work:0}));assert_eq!(calls,law["effectCallsBeforeRecovery"].as_u64().unwrap());
 let poll=control.receive_effect(demand,units,&mut frame,|_,effect|{calls+=1;assert_eq!(effect.maximum_work_units(),units);let actual=effect.actual();let(owner,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||{*actual=Some(0);let pointer=unsafe{std::alloc::alloc(std::alloc::Layout::array::<u8>(bytes).unwrap())};assert!(!pointer.is_null());*actual=Some(bytes);unsafe{Vec::from_raw_parts(pointer,0,bytes)}});assert_eq!(heap,(bytes,0));output=Some(owner);RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{retained_capacity_bytes:bytes,..Default::default()})),work:units}})?;let NativeReceivingEffectPoll::Complete(turn)=poll else{panic!("original accepted quote did not settle")};assert!(turn.result.is_ok());assert_eq!(turn.work,units);assert_eq!(calls,law["effectCallsAfterRecovery"].as_u64().unwrap());assert!(!control.has_pending_work());Ok::<_,ValueError>(())
 })).map_err(|error|error)?).unwrap()}).unwrap();let port=allocation.into_port().ok().unwrap();assert_eq!(port.quotes,law["quoteCalls"].as_u64().unwrap()as usize);assert!(port.pending.is_none());assert_eq!(port.posts,1);assert!(physical.into_recipient().is_ok());assert!(work.into_recipient().is_ok());drop(output.take());
}
